#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/timing/timing.h>

#define STACK_SIZE 512
#define THREAD_PRIORITY K_PRIO_PREEMPT(0)

static struct k_event test_event;

/* Helper thread for event waiting */
static void event_wait_thread(void *p1, void *p2, void *p3)
{
    uint32_t events_to_wait = (uint32_t)p1;
    uint32_t options = (uint32_t)p2;
    k_timeout_t timeout = K_FOREVER;
    uint32_t *received_events_ptr = (uint32_t *)p3;

    uint32_t received_events = k_event_wait(&test_event, events_to_wait, options, timeout);
    if (received_events_ptr) {
        *received_events_ptr = received_events;
    }
}

/* Helper thread for event setting */
static void event_set_thread(void *p1, void *p2, void *p3)
{
    uint32_t events_to_set = (uint32_t)p1;
    k_event_set(&test_event, events_to_set);
}

/*
 * Test case: test_event_post
 * Description: Verify that events can be posted (set) to an event object.
 */
ZTEST(events_api, test_event_post)
{
    k_event_init(&test_event);
    k_event_set(&test_event, 0x1);
    zassert_equal(test_event.events, 0x1, "Event 0x1 not set");

    k_event_set(&test_event, 0x2);
    zassert_equal(test_event.events, 0x3, "Event 0x2 not set, or 0x1 cleared");

    k_event_set(&test_event, 0x4);
    zassert_equal(test_event.events, 0x7, "Event 0x4 not set");
}

/*
 * Test case: test_event_receive_existing
 * Description: Verify that a thread can receive events that are already set.
 */
ZTEST(events_api, test_event_receive_existing)
{
    k_event_init(&test_event);
    k_event_set(&test_event, 0xABC); /* Set some events */

    uint32_t received_events = k_event_wait(&test_event, 0xABC, K_EVENT_WAIT_ALL, K_NO_WAIT);
    zassert_equal(received_events, 0xABC, "Did not receive all existing events");
    zassert_equal(test_event.events, 0xABC, "Events cleared unexpectedly"); /* K_EVENT_WAIT_RESET not used */

    k_event_init(&test_event);
    k_event_set(&test_event, 0x123);
    received_events = k_event_wait(&test_event, 0x100, K_EVENT_WAIT_ANY, K_NO_WAIT);
    zassert_equal(received_events, 0x100, "Did not receive any existing event");
    zassert_equal(test_event.events, 0x123, "Events cleared unexpectedly");
}

/*
 * Test case: test_event_reset_on_wait
 * Description: Verify that events are reset (cleared) from the event object
 *              when K_EVENT_WAIT_RESET option is used.
 */

static K_THREAD_STACK_DEFINE(tstack_reset, STACK_SIZE);
static struct k_thread tdata_reset;
static uint32_t received_events_from_thread;

static void drive_reset_on_wait(uint32_t events_to_set, uint32_t events_to_wait, uint32_t options)
{
    k_event_init(&test_event);
    received_events_from_thread = 0;

    k_event_set(&test_event, events_to_set);

    k_tid_t tid = k_thread_create(&tdata_reset, tstack_reset, K_THREAD_STACK_SIZEOF(tstack_reset),
                                  event_wait_thread, (void *)events_to_wait, (void *)options,
                                  &received_events_from_thread, THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_join(tid, K_FOREVER);

    /*
     * The original assertion at line 312 was likely:
     * zassert_equal(test_event.events, 0x123, "test_event.events == 0x123 is false");
     * However, for a test named "test_event_reset_on_wait" using K_EVENT_WAIT_RESET,
     * if all events are waited for, they should be cleared from the event object.
     * Thus, the expected value should be 0.
     */
    zassert_equal(test_event.events, 0, "Events should be reset to 0 after wait with K_EVENT_WAIT_RESET");
    zassert_equal(received_events_from_thread, events_to_wait, "Thread did not receive expected events");
}

ZTEST(events_api, test_event_reset_on_wait)
{
    /* Test with K_EVENT_WAIT_ALL | K_EVENT_WAIT_RESET */
    drive_reset_on_wait(0x123, 0x123, K_EVENT_WAIT_ALL | K_EVENT_WAIT_RESET);

    /* Test with K_EVENT_WAIT_ANY | K_EVENT_WAIT_RESET (partial reset) */
    k_event_init(&test_event);
    k_event_set(&test_event, 0xABC);
    received_events_from_thread = 0;
    k_tid_t tid = k_thread_create(&tdata_reset, tstack_reset, K_THREAD_STACK_SIZEOF(tstack_reset),
                                  event_wait_thread, (void *)0xA00, (void *)(K_EVENT_WAIT_ANY | K_EVENT_WAIT_RESET),
                                  &received_events_from_thread, THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_join(tid, K_FOREVER);
    zassert_equal(test_event.events, 0xBC, "Events not partially reset correctly");
    zassert_equal(received_events_from_thread, 0xA00, "Thread did not receive expected events for partial reset");
}


ZTEST_SUITE(events_api, NULL, NULL, NULL, NULL, NULL);
